{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Niraparib, an oral anticancer small molecule with a heteroaromatic core and basic amine, has a measured human absolute oral bioavailability of 72.7% (90% CI 61.69–83.40), supporting high F for a similar oral kinase-inhibitor-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Trametinib, a pyridopyrimidine-based oral kinase inhibitor, has a measured absolute oral bioavailability of 72.3% in patients with solid tumours, supporting high F for the structurally related pyridopyrimidinone query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Brigatinib, an oral kinase inhibitor with an aniline-pyrimidine and solubilizing piperazine/piperidine motif, has an absolute oral bioavailability of 57% in fasted healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Imatinib, an oral kinase inhibitor containing a piperazine and aminopyrimidine, is almost completely absorbed with a mean absolute bioavailability of 98%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brepocitinib, an oral small-molecule kinase inhibitor, has an estimated absolute bioavailability of 75% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Risdiplam, an oral small molecule with a piperazine-containing heteroaromatic structure, has high oral bioavailability due to complete absorption and negligible first-pass effects, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Palbociclib is predicted to have high absolute oral bioavailability (F ≥ 20%), supported by multiple human absolute F values of 46–98% in related oral kinase inhibitors and by palbociclib's established F of approximately 46%.",
  "evidence_gaps": [
    "No direct palbociclib absolute bioavailability record is present in the supplied evidence; the prediction relies on structurally and mechanistically related oral kinase inhibitors.",
    "The mCPP record shows a wide F range (12–84%) but is structurally unrelated and does not provide affirmative threshold-relevant evidence for low F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

